Class Producto
  Define precio As Integer;

  Method Constructor(p As Integer)
    This.precio <- p;
  EndMethod

  Method PrecioFinal() As Integer
    Return This.precio;
  EndMethod
EndClass

Class ProductoVencible Inherits From Producto
  Method Constructor(p As Integer)
    Super.constructor(p);
  EndMethod

  Method PrecioFinal() As Integer
    Return This.precio Div 2;
  EndMethod
EndClass

Class ProductoEnOferta Inherits From Producto
  Method Constructor(p As Integer)
    Super.constructor(p);
  EndMethod

  Method PrecioFinal() As Integer
    Return This.precio - This.precio * 25 Div 100;
  EndMethod
EndClass

Algorithm Kiosco
  Define tipo, precio As Integer;
  Read tipo;
  Read precio;
  Define producto As Producto <- New Producto(precio);
  If tipo = 2 Then
    producto <- New ProductoVencible(precio);
  EndIf
  If tipo = 3 Then
    producto <- New ProductoEnOferta(precio);
  EndIf
  Write producto.PrecioFinal();
EndAlgorithm

